from __future__ import annotations

import collections.abc as cabc
import typing as t
from datetime import datetime

from .._internal import _plain_int
from ..http import http_date
from ..http import is_byte_range_valid
from ..http import parse_date
from .etag import ETag

if t.TYPE_CHECKING:
    import typing_extensions as te

T = t.TypeVar("T")


class IfRange:
    """A parsed ``If-Range`` header. Either a strong ETag or a datetime, but not
    both. Weak ETag values must not be used.

    :attr:`.Request.if_range` returns an instance.

    :param etag: An unquoted strong ETag value.
    :param date: A timezone-aware datetime.

    .. versionadded:: 0.7
    """

    def __init__(self, etag: str | None = None, date: datetime | None = None):
        self.etag = etag
        """An unquoted strong ETag value."""

        self.date = date
        """A timezone-aware datetime."""

    @classmethod
    def from_header(cls, value: str | None) -> te.Self:
        """Parse an ``If-Range`` header value and create an instance of this
        class. A weak ETag value is discarded.

        .. versionadded:: 3.2
        """
        if not value:
            return cls()

        if (date := parse_date(value)) is not None:
            return cls(date=date)

        if (etag := ETag.from_header(value)) is None or etag.weak:
            return cls()

        return cls(etag=etag.value)

    def to_header(self) -> str:
        """Convert to an ``If-Range`` header value."""
        if self.date is not None:
            return http_date(self.date)

        if self.etag is not None:
            return ETag(self.etag).to_header()

        return ""

    def __bool__(self) -> bool:
        return self.etag is not None or self.date is not None

    def __str__(self) -> str:
        return self.to_header()

    def __repr__(self) -> str:
        return f"<{type(self).__name__} {str(self)!r}>"


class Range:
    """A parsed ``Range`` header.

    :attr:`.Request.range` returns an instance, or ``None`` if the header is not
    set.

    .. versionchanged:: 3.2
        Validation is done in ``from_header``. Values passed to the constructor
        are assumed valid.

    .. versionchanged:: 0.15
        Values passed to the constructor are validated.

    .. versionadded:: 0.7
    """

    def __init__(
        self, units: str, ranges: cabc.Sequence[tuple[int, int | None]]
    ) -> None:
        self.units = units
        """The unit being counted. Only ``"bytes"`` is defined."""

        self.ranges = ranges
        """The parsed ``(start, stop)`` ranges. ``stop`` is exclusive, unlike
        the raw header value. If ``stop`` is ``None``, ``start`` can be positive
        to get the remaining units from that offset, or negative to get that
        number of units from the end.
        """

    def range_for_length(self, length: int | None) -> tuple[int, int] | None:
        """Return the ``(start, stop)`` values to use for a
        :class:`.ContentRange` header with the given complete length. Or ``None``
        if a valid range cannot be constructed.

        This will generate a range regardless of the value of :attr:`units`.
        However, :meth:`.Response.make_conditional` can only handle ``bytes``.

        If there are multiple ranges in the header, this will only return the
        first range.

        :param length: The complete length of the content. ``None`` means the
            value is unknown, and will return ``None``.
        :return: ``(start, stop)`` if the range and length are valid, ``None``
            otherwise.

        .. deprecated:: 3.2
            Will be removed in Werkzeug 4.0. Use ``make_content_range`` instead.

        .. versionchanged:: 3.2
            Allows units other than ``bytes``. Will return the first range if
            there are multiple.
        """
        import warnings

        warnings.warn(
            "'range_for_length' is deprecated and will be removed in Werkzeug 4.0."
            " Use 'make_content_range` instead.",
            DeprecationWarning,
            stacklevel=2,
        )
        return self._private_range_for_length(length)

    def _private_range_for_length(self, length: int | None) -> tuple[int, int] | None:
        if length is None or not self.ranges:
            return None

        start, stop = self.ranges[0]

        if stop is None:
            stop = length

            if start < 0:
                start += length

        if not is_byte_range_valid(start, stop, length):
            return None

        return start, min(stop, length)

    def make_content_range(self, length: int | None) -> ContentRange | None:
        """Create a :class:`.ContentRange` with the given complete length. Or
        ``None`` if a valid range cannot be constructed.

        This will generate a range regardless of the value of :attr:`units`.
        However, :meth:`.Response.make_conditional` can only handle ``bytes``.

        If there are multiple ranges in the header, this will only return the
        first range.

        .. versionchanged:: 3.2
            Allows units other than ``bytes``. Will return the first range if
            there are multiple.
        """
        # TODO inline after deprecation
        if (bounds := self._private_range_for_length(length)) is None:
            return None

        return ContentRange(self.units, bounds[0], bounds[1], length)

    @classmethod
    def from_header(cls, value: str | None) -> te.Self | None:
        """Parse a ``Range`` header value and create an instance of this class,
        or ``None`` if the value is empty.

        .. versionadded:: 3.2
        """
        if not value or "=" not in value:
            return None

        ranges = []
        last_end = 0
        units, _, ranges_str = value.partition("=")
        units = units.strip(" \t").lower()

        for item in ranges_str.split(","):
            item = item.strip(" \t")

            if "-" not in item:
                return None

            if item.startswith("-"):
                if last_end < 0:
                    return None

                try:
                    begin = _plain_int(item)
                except ValueError:
                    return None

                # -0 will parse to 0, and is an invalid suffix length.
                if begin == 0:
                    return None

                end = None
                last_end = -1

            else:
                begin_str, _, end_str = item.partition("-")
                begin_str = begin_str.strip(" \t")
                end_str = end_str.strip(" \t")

                try:
                    begin = _plain_int(begin_str)
                except ValueError:
                    return None

                if begin < last_end or last_end < 0:
                    return None

                if end_str:
                    try:
                        end = _plain_int(end_str) + 1
                    except ValueError:
                        return None

                    if begin >= end:
                        return None
                else:
                    end = None

                last_end = end if end is not None else -1

            ranges.append((begin, end))

        return cls(units, ranges)

    def to_header(self) -> str:
        """Convert to a ``Range`` header value."""
        ranges = []
        for begin, end in self.ranges:
            if end is None:
                ranges.append(f"{begin}-" if begin >= 0 else str(begin))
            else:
                ranges.append(f"{begin}-{end - 1}")
        return f"{self.units}={','.join(ranges)}"

    def to_content_range_header(self, length: int | None) -> str | None:
        """Converts the object into `Content-Range` HTTP header,
        based on given length

        .. deprecated:: 3.2
            Will be removed in Werkzeug 4.0. Use ``make_content_range`` then
            call its ``to_header`` method instead.
        """
        import warnings

        warnings.warn(
            "'to_content_range_header' is deprecated and will be removed in"
            " Werkzeug 4.0. Use 'make_content_range` then call its 'to_header'"
            " method instead.",
            DeprecationWarning,
            stacklevel=2,
        )

        if (cr := self.make_content_range(length)) is None:
            return None

        return cr.to_header()

    def __str__(self) -> str:
        return self.to_header()

    def __repr__(self) -> str:
        return f"<{type(self).__name__} {str(self)!r}>"


class _CallbackProperty(t.Generic[T]):
    def __set_name__(self, owner: type[ContentRange], name: str) -> None:
        self.attr = f"_{name}"

    @t.overload
    def __get__(self, instance: None, owner: None) -> te.Self: ...
    @t.overload
    def __get__(self, instance: ContentRange, owner: type[ContentRange]) -> T: ...
    def __get__(
        self, instance: ContentRange | None, owner: type[ContentRange] | None
    ) -> te.Self | T:
        if instance is None:
            return self

        return instance.__dict__[self.attr]  # type: ignore[no-any-return]

    def __set__(self, instance: ContentRange, value: T) -> None:
        instance.__dict__[self.attr] = value

        if instance._on_update is not None:
            instance._on_update(instance)


class ContentRange:
    """A parsed ``Content-Range`` header.

    Set :attr:`.Response.content_range` to an instance to set the header.
    Modifying the instance will update the header.

    .. versionchanged:: 3.2
        The ``on_update`` parameter was removed. Argument defaults were added.
        Considered false if neither a range nor length is set.

    .. versionadded:: 0.7
    """

    def __init__(
        self,
        units: str = "bytes",
        start: int | None = None,
        stop: int | None = None,
        length: int | None = None,
    ) -> None:
        self._units = units
        self._start = start
        self._stop = stop
        self._length = length
        self._on_update: cabc.Callable[[ContentRange], None] | None = None

    units: str = _CallbackProperty()  # type: ignore[assignment]
    """The unit being counted. Only ``"bytes"`` is defined."""

    start: int | None = _CallbackProperty()  # type: ignore[assignment]
    """The start point, inclusive. ``None`` means the range is unsatisfiable."""

    stop: int | None = _CallbackProperty()  # type: ignore[assignment]
    """The stop point. Exclusive, unlike the raw header value. ``None`` means
    the range is unsatisfiable.
    """

    length: int | None = _CallbackProperty()  # type: ignore[assignment]
    """The complete length of the content. ``None`` means the length is unknown."""

    def set(
        self,
        start: int | None,
        stop: int | None,
        length: int | None = None,
        units: str = "bytes",
    ) -> None:
        """Update the header.

        .. deprecated:: 3.2
            Will be removed in Werkzeug 4.0. Use
            ``request.content_range = ContentRange(...)`` instead.
        """
        import warnings

        warnings.warn(
            "The 'set' method is deprecated and will be removed in Werkzeug 4.0."
            " Use 'request.content_range = ContentRange(...)' instead.",
            DeprecationWarning,
            stacklevel=2,
        )
        self._units = units
        self._start = start
        self._stop = stop
        self._length = length

        if self._on_update is not None:
            self._on_update(self)

    def unset(self) -> None:
        """Unset the header.

        .. deprecated:: 3.2
            Will be removed in Werkzeug 4.0. Use ``del request.content_range``
            instead.
        """
        import warnings

        warnings.warn(
            "The 'unset' method is deprecated and will be removed in Werkzeug 4.0."
            " Use 'del request.content_range' instead.",
            DeprecationWarning,
            stacklevel=2,
        )
        self.set(None, None, units="")

    @classmethod
    def from_header(cls, value: str | None) -> te.Self:
        """Parse a ``Content-Range`` header value and create an instance of this class.

        .. versionadded:: 3.2
        """
        if not value:
            return cls()

        units, _, range_str = value.partition(" ")
        range_str, sep, length_str = range_str.partition("/")

        if not sep:
            return cls()

        if length_str == "*":
            length = None
        else:
            try:
                length = _plain_int(length_str)
            except ValueError:
                return cls()

            if length < 0:
                return cls()

        if range_str == "*":
            if length_str == "*":
                return cls()

            return cls(units, None, None, length)

        start_str, sep, stop_str = range_str.partition("-")

        if not sep:
            return cls()

        try:
            start = _plain_int(start_str)
            stop = _plain_int(stop_str)
        except ValueError:
            return cls()

        if not (0 <= start <= stop) or (length is not None and length <= stop):
            return cls()

        return cls(units, start, stop + 1, length)

    def to_header(self) -> str:
        """Convert to a ``Content-Range`` header value."""
        if not self:
            return ""

        length = "*" if self._length is None else self._length

        if self._start is None or self._stop is None:
            return f"{self._units} */{length}"

        return f"{self._units} {self._start}-{self._stop - 1}/{length}"

    def __bool__(self) -> bool:
        return not (
            (self._start is None or self._stop is None) and self._length is None
        )

    def __str__(self) -> str:
        return self.to_header()

    def __repr__(self) -> str:
        return f"<{type(self).__name__} {self.to_header()}>"

from __future__ import annotations

import collections.abc as cabc
import re
import typing as t

if t.TYPE_CHECKING:
    import typing_extensions as te


class ETag:
    """A parsed ETag value.

    Set :attr:`.Response.etag` to an instance to set the header. Modifying the
    instance will update the header.

    .. versionadded:: 3.2
    """

    _on_update: t.Callable[[ETag], None] | None = None

    def __init__(self, value: str, weak: bool = False) -> None:
        self._value = value
        self._weak = weak

    def _trigger_on_update(self) -> None:
        if self._on_update is not None:
            self._on_update(self)

    @property
    def value(self) -> str:
        """The unquoted value."""
        return self._value

    @value.setter
    def value(self, value: str) -> None:
        self._value = value
        self._trigger_on_update()

    @property
    def weak(self) -> bool:
        """Whether the weak marker is present."""
        return self._weak

    @weak.setter
    def weak(self, value: bool) -> None:
        self._weak = value
        self._trigger_on_update()

    @classmethod
    def from_header(cls, value: str | None) -> te.Self | None:
        """Parse a quoted ETag value and create an instance of this class, or
        ``None`` if the value is empty or invalid.
        """

        if not value:
            return None

        weak = False
        start = 0

        if value.startswith(("W/", "w/")):
            weak = True
            start = 2

        if not (value.startswith('"', start) and value.endswith('"', start)):
            # invalid, value must be quoted
            return None

        return cls(value[start + 1 : -1], weak)

    def to_header(self) -> str:
        if not self.value or '"' in self.value:
            return ""

        if self.weak:
            return f'W/"{self.value}"'

        return f'"{self.value}"'

    def __bool__(self) -> bool:
        return bool(self._value)

    def __eq__(self, value: object, /) -> bool:
        if not isinstance(value, type(self)):
            return NotImplemented

        return self._value == value._value and self._weak == value._weak

    def __str__(self) -> str:
        return self.to_header()

    def __repr__(self) -> str:
        return f"<ETag {self.value!r} {'weak' if self.weak else 'strong'}>"


_etag_re = re.compile(
    r"""
    [ \t]*  # ignore leading space
    ([Ww]/)?  # optional weak marker
    "([^"]*)"  # quoted value
    [ \t]*  # ignore trailing space
    (?:,|\Z)  # only if followed by comma or end
    """,
    flags=re.ASCII | re.VERBOSE,
)


class ETagSet:
    """A parsed ``If-Match`` or ``If-None-Match`` header.

    :attr:`.Request.if_match` and :attr:`.Request.if_none_match` return an
    instance.

    :param strong_etags: Unquoted values that were not marked weak.
    :param weak_etags: Unquoted values that were marked weak.
    :param star_tag: Whether ``*`` is present in the header value.

    .. versionchanged:: 3.2
        Renamed from ``ETags``.

        No longer inherits ``Collection``. ``__len__``, ``__iter__``, and
        ``__contains__`` are deprecated and will be removed in Werkzeug 4.0.
    """

    def __init__(
        self,
        strong_etags: cabc.Iterable[str] | None = None,
        weak_etags: cabc.Iterable[str] | None = None,
        star_tag: bool = False,
    ):
        if not star_tag and strong_etags:
            self._strong = frozenset(strong_etags)
        else:
            self._strong = frozenset()

        self._weak = frozenset(weak_etags or ())
        self.star_tag = star_tag

    def as_set(self, include_weak: bool = False) -> set[str]:
        """The values as a :class:`set`. Strong values are always included, weak
        values are optional.

        :param include_weak: Include weak values along with strong values.

        .. deprecated:: 3.2
            Will be removed in Werkzeug 4.0.
        """
        import warnings

        warnings.warn(
            "'as_set' is deprecated and will be removed in Werkzeug 4.0.",
            DeprecationWarning,
            stacklevel=2,
        )
        rv = set(self._strong)

        if include_weak:
            rv.update(self._weak)

        return rv

    def is_weak(self, etag: str) -> bool:
        """Check if the given value is in the weak set. Does not check the
        strong set or ``*``.

        :param etag: The unquoted value to check.

        .. deprecated:: 3.2
            Will be removed in Werkzeug 4.0. Use ``contains_weak`` instead.
        """
        import warnings

        warnings.warn(
            "'is_weak' is deprecated and will be removed in Werkzeug 4.0. Use"
            " 'contains_weak' instead.",
            DeprecationWarning,
            stacklevel=2,
        )
        return etag in self._weak

    def is_strong(self, etag: str) -> bool:
        """Check if the given value is in the strong set. Does not check the
        weak set or ``*``.

        :param etag: The unquoted value to check.

        .. deprecated:: 3.2
            Will be removed in Werkzeug 4.0. Use ``contains_strong`` instead.
        """
        import warnings

        warnings.warn(
            "'is_strong' is deprecated and will be removed in Werkzeug 4.0. Use"
            " 'contains_strong' instead.",
            DeprecationWarning,
            stacklevel=2,
        )

        return etag in self._strong

    def contains_strong(self, etag: ETag | str | None) -> bool:
        """The strong comparison function. Check if an ETag is in the strong
        set, ignoring the weak set. If the header is ``*``, all non-empty values
        are contained. If the ETag is weak, it is not contained.

        :param etag: The value to check. A ``str`` is assumed to be an unquoted
            strong value.

        .. versionchanged:: 3.2
            Renamed from ``contains``.

            Accepts an ``ETag`` or ``None``.
        """
        if not etag:
            return False

        if self.star_tag:
            return True

        if isinstance(etag, ETag):
            if etag.weak:
                return False

            return etag.value in self._strong

        return etag in self._strong

    def contains_weak(self, etag: ETag | str | None) -> bool:
        """The weak comparison function. Check if an ETag is in the strong or
        weak set. If the header is ``*``, all non-empty values are contained.
        The ETag can be strong or weak.

        :param etag: The value to check. A ``str`` is assumed to be an unquoted
            value.

        .. versionchanged:: 3.2
            Accepts an ``ETag`` or ``None``.
        """
        if not etag:
            return False

        if self.star_tag:
            return True

        value = etag.value if isinstance(etag, ETag) else etag
        return value in self._weak or value in self._strong

    def contains(self, etag: ETag | str | None) -> bool:
        """The strong comparison function. Check if an ETag is in the strong
        set, ignoring the weak set. If the header is ``*``, all non-empty values
        are contained. If the ETag is weak, it is not contained.

        :param etag: The value to check. A ``str`` is assumed to be an unquoted
            strong value.

        .. deprecated:: 3.2
            Renamed to ``contains_strong``. Will be removed in Werkzeug 4.0.

        .. versionchanged:: 3.2
            Accepts an ``ETag`` or ``None``.
        """
        import warnings

        warnings.warn(
            "'contains' is renamed to 'contains_strong'. The old name is deprecated and"
            " will be removed in Werkzeug 4.0.",
            DeprecationWarning,
            stacklevel=2,
        )
        return self.contains_strong(etag)

    def contains_raw(self, etag: str) -> bool:
        """Check if the raw, quoted value is part of the set. Parses the value,
        then calls :meth:`contains_weak` if it is weak, otherwise
        :meth:`contains`.

        :param etag: The raw, quoted value to check.

        .. deprecated:: 3.2
            Will be removed in Werkzeug 4.0. Use ``ETag.from_header`` and
            ``contains_strong`` or ``contains_weak``.
        """
        import warnings

        warnings.warn(
            "'contains_raw' is deprecated and will be removed in Werkzeug 4.0. Use"
            "'ETag.from_header' and 'contains_strong' or 'contains_weak'.",
            DeprecationWarning,
            stacklevel=2,
        )

        if (value := ETag.from_header(etag)) is None:
            return False

        if value.weak:
            return self.contains_weak(value)

        return self.contains_strong(value)

    @classmethod
    def from_header(cls, value: str | None) -> te.Self:
        """Parse a header value and create an instance of this class. Invalid
        items are discarded.

        .. versionadded:: 3.2
        """
        if not value:
            return cls()

        if value == "*":
            return cls(star_tag=True)

        strong = []
        weak = []
        pos = 0

        while True:
            if (m := _etag_re.match(value, pos)) is None:
                # Skip invalid chars until the next comma or end.
                if (pos := value.find(",", pos) + 1) == 0:
                    break

                continue

            is_weak, tag = m.groups()
            pos = m.end()

            if is_weak:
                weak.append(tag)
            else:
                strong.append(tag)

        return cls(strong, weak)

    def to_header(self) -> str:
        """Convert to a header value."""
        if self.star_tag:
            return "*"

        return ", ".join(
            [f'"{x}"' for x in self._strong] + [f'W/"{x}"' for x in self._weak]
        )

    def __call__(
        self,
        etag: ETag | str | None = None,
        data: bytes | None = None,
        include_weak: bool = False,
    ) -> bool:
        """Check if the given unquoted ETag value, or an ETag value generated by
        hashing the given data, is in the set.

        :param etag: The unquoted ETag value to check.
        :param data: The data to generate an ETag value for and check.
        :param include_weak: Use :meth:`contains_weak` instead of
            :meth:`contains`.

        .. deprecated:: 3.2
            Will be removed in Werkzeug 4.0. Use ``ETag.from_header`` and
            ``contains_strong`` or ``contains_weak``.

        .. versionchanged:: 3.2
            The ``*`` header value is considered.
        """
        import warnings

        warnings.warn(
            "Calling 'ETagSet' is deprecated and will be removed in Werkzeug 4.0. Use"
            "'ETag.from_header' and 'contains_strong' or 'contains_weak'.",
            DeprecationWarning,
            stacklevel=2,
        )

        if etag is None:
            if data is None:
                raise TypeError("'data' is required when 'etag' is not given.")

            from ..http import generate_etag

            etag = generate_etag(data)

        if include_weak:
            return self.contains_weak(etag)

        return self.contains_strong(etag)

    def __bool__(self) -> bool:
        return bool(self.star_tag or self._strong or self._weak)

    def __str__(self) -> str:
        return self.to_header()

    def __len__(self) -> int:
        import warnings

        warnings.warn(
            "Calling 'len' on 'ETagSet' is deprecated and will be removed in"
            " Werkzeug 4.0.",
            DeprecationWarning,
            stacklevel=2,
        )
        return len(self._strong)

    def __iter__(self) -> cabc.Iterator[str]:
        import warnings

        warnings.warn(
            "Iterating over 'ETagSet' is deprecated and will be removed in"
            " Werkzeug 4.0.",
            DeprecationWarning,
            stacklevel=2,
        )
        return iter(self._strong)

    def __contains__(self, etag: ETag | str | None) -> bool:
        import warnings

        warnings.warn(
            "Using 'in' with 'ETagSet' is deprecated and will be removed in"
            " Werkzeug 4.0. Use 'contains_strong' instead.",
            DeprecationWarning,
            stacklevel=2,
        )
        return self.contains_strong(etag)

    def __repr__(self) -> str:
        return f"<{type(self).__name__} {str(self)!r}>"


if not t.TYPE_CHECKING:

    def __getattr__(name: str) -> t.Any:
        if name == "ETags":
            import warnings

            warnings.warn(
                "'ETags' has been renamed to 'ETagSet'. The old name is deprecated and"
                " will be removed in Werkzeug 4.0.",
                DeprecationWarning,
                stacklevel=2,
            )
            return ETagSet

        raise AttributeError(name)
